-- All Grants Fund grants and yearly AGF totals from GiveWell's public sources, generated by
--   node -r ts-node/register/transpile-only scripts/agf-grants.ts fetch > agf.json
--   node -r ts-node/register/transpile-only scripts/agf-grants.ts sql agf.json --by migration:20261101230100_impact_agf_data
-- on 2026-11-01 (docs/impact-givewell-numbers.md › All Grants Fund grants). Upserts: running the
-- same statements again changes nothing, and rows edited in the admin keep their values. Each new
-- row gets an Impact_changes row by 'migration:20261101230100_impact_agf_data'. Organization_ID
-- links rows to our Organizations by abbriv where donors can give to the organisation through us.
--
-- Rollback: DELETE FROM Impact_fund_portfolio / Impact_givewell_grants / Impact_changes WHERE
-- created_by / changed_by = 'migration:20261101230100_impact_agf_data'.

AS new ON DUPLICATE KEY UPDATE
  `organization` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`organization`, `Impact_fund_portfolio`.`organization`),
  `organization_key` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`organization_key`, `Impact_fund_portfolio`.`organization_key`),
  `program` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`program`, `Impact_fund_portfolio`.`program`),
  `amount_cents` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`amount_cents`, `Impact_fund_portfolio`.`amount_cents`),
  `source_name` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`source_name`, `Impact_fund_portfolio`.`source_name`),
  `source_url` = IF(`Impact_fund_portfolio`.updated_by IS NULL, new.`source_url`, `Impact_fund_portfolio`.`source_url`);

AS new ON DUPLICATE KEY UPDATE
  `title` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`title`, `Impact_givewell_grants`.`title`),
  `organization` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`organization`, `Impact_givewell_grants`.`organization`),
  `organization_key` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`organization_key`, `Impact_givewell_grants`.`organization_key`),
  `location` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`location`, `Impact_givewell_grants`.`location`),
  `grant_type` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`grant_type`, `Impact_givewell_grants`.`grant_type`),
  `recommended_month` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`recommended_month`, `Impact_givewell_grants`.`recommended_month`),
  `published_month` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`published_month`, `Impact_givewell_grants`.`published_month`),
  `amount_cents` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`amount_cents`, `Impact_givewell_grants`.`amount_cents`),
  `amount_exact` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`amount_exact`, `Impact_givewell_grants`.`amount_exact`),
  `funders` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`funders`, `Impact_givewell_grants`.`funders`),
  `fund_amount_cents` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`fund_amount_cents`, `Impact_givewell_grants`.`fund_amount_cents`),
  `ce_low` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`ce_low`, `Impact_givewell_grants`.`ce_low`),
  `ce_high` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`ce_high`, `Impact_givewell_grants`.`ce_high`),
  `ce_benchmark` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`ce_benchmark`, `Impact_givewell_grants`.`ce_benchmark`),
  `outputs` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`outputs`, `Impact_givewell_grants`.`outputs`),
  `output_unit` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`output_unit`, `Impact_givewell_grants`.`output_unit`),
  `cents_per_output` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`cents_per_output`, `Impact_givewell_grants`.`cents_per_output`),
  `deaths_averted` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`deaths_averted`, `Impact_givewell_grants`.`deaths_averted`),
  `sources` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`sources`, `Impact_givewell_grants`.`sources`),
  `source_url` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`source_url`, `Impact_givewell_grants`.`source_url`),
  `notes` = IF(`Impact_givewell_grants`.updated_by IS NULL, new.`notes`, `Impact_givewell_grants`.`notes`);

UPDATE `Impact_fund_portfolio` t JOIN `Organizations` o ON o.abbriv = CASE t.organization_key
  WHEN 'Against Malaria Foundation' THEN 'AMF'
  WHEN 'Malaria Consortium' THEN 'MC'
  WHEN 'Helen Keller Intl' THEN 'HKI'
  WHEN 'New Incentives' THEN 'NI'
  WHEN 'GiveDirectly' THEN 'GD'
  WHEN 'Sightsavers' THEN 'Sight'
  WHEN 'The END Fund' THEN 'End'
  WHEN 'Unlimit Health' THEN 'SCI'
  WHEN 'The Taimaka Project' THEN 'TMK'
  WHEN 'One Acre Fund' THEN 'OAF'
  WHEN 'Clear Solutions' THEN 'CS'
  WHEN 'Access to Medicines Initiative' THEN 'AMI'
  WHEN 'MiracleFeet' THEN 'MF'
  WHEN 'Lafiya' THEN 'LAF'
  WHEN 'Fortify Health' THEN 'FH'
  WHEN 'Family Empowerment Media' THEN 'FEM'
  WHEN 'Development Innovation Lab' THEN 'DIL'
END
SET t.Organization_ID = o.ID
WHERE t.Organization_ID IS NULL;

UPDATE `Impact_givewell_grants` t JOIN `Organizations` o ON o.abbriv = CASE t.organization_key
  WHEN 'Against Malaria Foundation' THEN 'AMF'
  WHEN 'Malaria Consortium' THEN 'MC'
  WHEN 'Helen Keller Intl' THEN 'HKI'
  WHEN 'New Incentives' THEN 'NI'
  WHEN 'GiveDirectly' THEN 'GD'
  WHEN 'Sightsavers' THEN 'Sight'
  WHEN 'The END Fund' THEN 'End'
  WHEN 'Unlimit Health' THEN 'SCI'
  WHEN 'The Taimaka Project' THEN 'TMK'
  WHEN 'One Acre Fund' THEN 'OAF'
  WHEN 'Clear Solutions' THEN 'CS'
  WHEN 'Access to Medicines Initiative' THEN 'AMI'
  WHEN 'MiracleFeet' THEN 'MF'
  WHEN 'Lafiya' THEN 'LAF'
  WHEN 'Fortify Health' THEN 'FH'
  WHEN 'Family Empowerment Media' THEN 'FEM'
  WHEN 'Development Innovation Lab' THEN 'DIL'
END
SET t.Organization_ID = o.ID
WHERE t.Organization_ID IS NULL;

SELECT 'agf_summary', t.ID, 'create', NULL, LEFT(CONCAT('AGF ', t.metrics_year, ': ', t.organization, IFNULL(CONCAT(' – ', t.program), '')), 255), NULL, JSON_OBJECT('fund', t.`fund`, 'metricsYear', t.`metrics_year`, 'rowKey', t.`row_key`, 'organization', t.`organization`, 'organizationKey', t.`organization_key`, 'program', t.`program`, 'amountCents', t.`amount_cents`, 'sourceName', t.`source_name`, 'sourceUrl', t.`source_url`), 'migration:20261101230100_impact_agf_data', UTC_TIMESTAMP()
FROM `Impact_fund_portfolio` t
WHERE t.created_by = 'migration:20261101230100_impact_agf_data'
  AND NOT EXISTS (SELECT 1 FROM `Impact_changes` c WHERE c.entity = 'agf_summary' AND c.entity_id = t.ID);

SELECT 'givewell_grant', t.ID, 'create', NULL, LEFT(t.title, 255), NULL, JSON_OBJECT('slug', t.`slug`, 'title', t.`title`, 'organization', t.`organization`, 'organizationKey', t.`organization_key`, 'location', t.`location`, 'grantType', t.`grant_type`, 'recommendedMonth', t.`recommended_month`, 'publishedMonth', t.`published_month`, 'amountCents', t.`amount_cents`, 'amountExact', t.`amount_exact`, 'funders', t.`funders`, 'fundAmountCents', t.`fund_amount_cents`, 'ceLow', t.`ce_low`, 'ceHigh', t.`ce_high`, 'ceBenchmark', t.`ce_benchmark`, 'outputs', t.`outputs`, 'outputUnit', t.`output_unit`, 'centsPerOutput', t.`cents_per_output`, 'deathsAverted', t.`deaths_averted`, 'sources', t.`sources`, 'sourceUrl', t.`source_url`, 'notes', t.`notes`), 'migration:20261101230100_impact_agf_data', UTC_TIMESTAMP()
FROM `Impact_givewell_grants` t
WHERE t.created_by = 'migration:20261101230100_impact_agf_data'
  AND NOT EXISTS (SELECT 1 FROM `Impact_changes` c WHERE c.entity = 'givewell_grant' AND c.entity_id = t.ID);

